using System.Reflection;
using Sharpy.TestInfrastructure.Oracles;
using Xunit;

namespace Sharpy.Stdlib.Tests.Conformance;

/// <summary>
/// C3 of plan-638e8b (P33, #2087; COMPARED row 3 of <c>docs/design/python-fidelity-scope.md</c>): a
/// Stdlib exception whose python namesake has <c>OSError</c> in its <c>__mro__</c> is assignable to
/// Core <c>OSError</c>, so <c>except OSError</c> catches it as in python — and, the same rule read
/// backwards, a Stdlib exception whose namesake is outside the <c>OSError</c> family is not.
/// <para><b>Rows.</b> GENERATED by reflection over the <c>Sharpy.Stdlib</c> assembly: every public
/// type assignable to <see cref="System.Exception"/> (<see cref="GeneratedTypes"/>), never a
/// hand-written list, so a new Stdlib exception cannot land unmeasured.</para>
/// <para><b>Namesake map</b> (<see cref="Resolve"/>) — three rules tried in this order, the first match
/// deciding, so a package installed on the host can never decide a lookup:
/// (1) <see cref="ExcludedModules"/> — third-party modules, absent from CPython's library, excluded
/// by NAME; (2) the spelling tables — <see cref="TypeSpellings"/> keyed on the CLR type (the class
/// name differs, or the type carries no <c>[SharpyModuleType]</c>), then <see cref="ModuleSpellings"/>
/// keyed on the stamped module; (3) the stamped module and exported name, when python imports the
/// module and the name is a class there. A type no rule resolves is RED, never dropped. The import
/// test is an injected predicate, so the ORDER is asserted on any host
/// (<see cref="Spelling_table_decides_before_a_same_name_import"/>, plan deferred finding 2).</para>
/// <para><b>Oracle.</b> <c>python3</c>, ONE batch for the whole roster, through the shared
/// <see cref="PythonInterpreter.RequireOrSkip(int)"/> gate: absent → SKIPPED on a developer machine,
/// FAILED under <c>SHARPY_REQUIRE_PYTHON_ORACLE=1</c>.</para>
/// <para>The map is test-side only: stamping an attribute would change discovery (plan D3).</para>
/// </summary>
public class StdlibExceptionBasePythonTests
{
    internal enum Rule { Excluded, Spelling, SameName, Unresolved }

    internal sealed record Resolution(Rule Rule, string? Module, string? Name, string Detail);

    /// <summary>Rule 1: stamped modules that are not CPython's, excluded by name with the reason.</summary>
    internal static readonly IReadOnlyDictionary<string, string> ExcludedModules = new Dictionary<string, string>(StringComparer.Ordinal)
    {
        ["yaml"] = "third-party (PyYAML), absent from CPython's library",
        ["requests"] = "third-party (requests), absent from CPython's library",
    };

    /// <summary>Rule 2a: CLR type → python (module, class), where the class name differs or the type has no stamp.</summary>
    internal static readonly IReadOnlyDictionary<Type, (string Module, string Name)> TypeSpellings = new Dictionary<Type, (string, string)>
    {
        // Stamped [SharpyModuleType("struct")] with the CLR name; python spells it struct.error.
        [typeof(global::Sharpy.StructError)] = ("struct", "error"),
        // Carries no [SharpyModuleType] (`except statistics.StatisticsError` is SPY0202, plan ledger).
        [typeof(global::Sharpy.StatisticsError)] = ("statistics", "StatisticsError"),
    };

    /// <summary>Rule 2b: stamped module → the python module that defines its exceptions (python3 3.13.18 resolves each).</summary>
    internal static readonly IReadOnlyDictionary<string, string> ModuleSpellings = new Dictionary<string, string>(StringComparer.Ordinal)
    {
        ["http"] = "http.client",
        ["xml"] = "xml.etree.ElementTree",
        ["toml"] = "tomllib",
        // email's exceptions live in email.errors; `import email` does not export them.
        ["email"] = "email.errors",
    };

    private const string OracleScript = """
        import importlib, json, sys
        for line in sys.stdin:
            query = json.loads(line)
            cls = None
            try:
                cls = getattr(importlib.import_module(query["module"]), query["name"], None)
            except Exception:
                cls = None
            if isinstance(cls, type) and issubclass(cls, BaseException):
                mro = [c.__module__ + "." + c.__qualname__ for c in cls.__mro__]
            else:
                mro = None
            print(json.dumps({"module": query["module"], "name": query["name"], "mro": mro}))
        """;

    private static readonly object OracleLock = new();
    private static Dictionary<(string Module, string Name), string[]?>? _oracle;

    /// <summary>Every public exception type of the Stdlib assembly: the generated row set.</summary>
    internal static IReadOnlyList<Type> GeneratedTypes() =>
        typeof(global::Sharpy.SocketModule.Error).Assembly.GetExportedTypes()
            .Where(t => typeof(Exception).IsAssignableFrom(t))
            .OrderBy(t => t.FullName, StringComparer.Ordinal)
            .ToArray();

    public static IEnumerable<object[]> StdlibExceptionTypes() =>
        GeneratedTypes().Select(t => new object[] { t.FullName! });

    /// <summary>
    /// The namesake map. <paramref name="isPythonClass"/> answers rule 3: does python import
    /// <c>module</c> and find a class <c>name</c> in it. It is consulted LAST, so no host package can
    /// override a table row.
    /// </summary>
    internal static Resolution Resolve(Type type, Func<string, string, bool> isPythonClass)
    {
        var stamp = type.GetCustomAttribute<global::Sharpy.SharpyModuleTypeAttribute>();
        var exported = stamp?.PythonName ?? type.Name;

        if (stamp is not null && ExcludedModules.TryGetValue(stamp.ModuleName, out var reason))
            return new Resolution(Rule.Excluded, stamp.ModuleName, exported, reason);

        if (TypeSpellings.TryGetValue(type, out var spelled))
            return new Resolution(Rule.Spelling, spelled.Module, spelled.Name, "type-keyed spelling row");

        if (stamp is not null && ModuleSpellings.TryGetValue(stamp.ModuleName, out var module))
            return new Resolution(Rule.Spelling, module, exported, $"module-keyed spelling row `{stamp.ModuleName}`");

        if (stamp is not null && isPythonClass(stamp.ModuleName, exported))
            return new Resolution(Rule.SameName, stamp.ModuleName, exported, "stamped module and exported name");

        return new Resolution(Rule.Unresolved, stamp?.ModuleName, exported,
            stamp is null
                ? "no [SharpyModuleType] stamp and no type-keyed spelling row"
                : $"python has no class `{stamp.ModuleName}.{exported}` and no spelling row covers it");
    }

    /// <summary>
    /// Positive control: the roster is non-empty and holds <c>socket.error</c> (#2087's cell), which
    /// resolves by the same-name rule, so the theory cannot pass vacuously.
    /// </summary>
    [Fact]
    public void Generated_set_is_non_empty_and_holds_socket_error()
    {
        var types = GeneratedTypes();
        Assert.NotEmpty(types);
        Assert.Contains(typeof(global::Sharpy.SocketModule.Error), types);
        Assert.Contains(typeof(global::Sharpy.SocketModule.Timeout), types);

        var socketError = Resolve(typeof(global::Sharpy.SocketModule.Error), (m, n) => m == "socket" && n == "error");
        Assert.Equal(new Resolution(Rule.SameName, "socket", "error", "stamped module and exported name"), socketError);
    }

    /// <summary>
    /// Rule order, host-independent (plan deferred finding 2): with a predicate that reports EVERY
    /// module importable and every name a class — a host with third-party <c>toml</c>, <c>yaml</c>
    /// and <c>requests</c> installed — <c>toml</c>'s exceptions still resolve through the table to
    /// <c>tomllib</c>, and <c>yaml</c>/<c>requests</c> stay excluded.
    /// </summary>
    [Fact]
    public void Spelling_table_decides_before_a_same_name_import()
    {
        static bool Everything(string module, string name) => true;

        var toml = GeneratedTypes().Where(t => t.GetCustomAttribute<global::Sharpy.SharpyModuleTypeAttribute>()?.ModuleName == "toml").ToArray();
        Assert.Contains(typeof(global::Sharpy.TOMLDecodeError), toml);
        foreach (var type in toml)
        {
            var resolution = Resolve(type, Everything);
            Assert.True(resolution.Rule == Rule.Spelling && resolution.Module == "tomllib",
                $"{type.FullName}: with `toml` importable it resolved by {resolution.Rule} to `{resolution.Module}.{resolution.Name}`; " +
                "the spelling table must decide before a same-name import.");
        }

        foreach (var type in GeneratedTypes())
        {
            var module = type.GetCustomAttribute<global::Sharpy.SharpyModuleTypeAttribute>()?.ModuleName;
            if (module is not null && ExcludedModules.ContainsKey(module))
                Assert.Equal(Rule.Excluded, Resolve(type, Everything).Rule);
        }
    }

    /// <summary>Drain on stale: every exclusion and spelling row is used by a type of the roster.</summary>
    [Fact]
    public void Every_table_row_names_a_roster_type()
    {
        var types = GeneratedTypes();
        var stampedModules = types
            .Select(t => t.GetCustomAttribute<global::Sharpy.SharpyModuleTypeAttribute>()?.ModuleName)
            .Where(m => m is not null).ToHashSet(StringComparer.Ordinal);
        foreach (var module in ExcludedModules.Keys.Concat(ModuleSpellings.Keys))
            Assert.True(stampedModules.Contains(module), $"table row `{module}` names a module no Stdlib exception is stamped with: delete it.");
        foreach (var type in TypeSpellings.Keys)
            Assert.True(types.Contains(type), $"type-keyed row `{type.FullName}` is not a public Stdlib exception: delete it.");
    }

    /// <summary>
    /// One row per Stdlib exception: its namesake resolves, and it is assignable to Core
    /// <c>OSError</c> exactly when python's namesake has <c>OSError</c> in its <c>__mro__</c>.
    /// </summary>
    [SkippableTheory]
    [MemberData(nameof(StdlibExceptionTypes))]
    public void OSError_family_membership_matches_python(string fullName)
    {
        var type = GeneratedTypes().Single(t => t.FullName == fullName);
        var oracle = Oracle();
        var resolution = Resolve(type, (m, n) => oracle.TryGetValue((m, n), out var mro) && mro is not null);

        if (resolution.Rule == Rule.Excluded)
            return; // by name, with its reason (ExcludedModules); not a CPython module

        Assert.True(resolution.Rule != Rule.Unresolved,
            $"{fullName}: no rule resolves its python namesake ({resolution.Detail}). Answer it with a spelling-table row " +
            "after checking python3 — an unresolved Stdlib exception is never dropped.");

        Assert.True(oracle.TryGetValue((resolution.Module!, resolution.Name!), out var pythonMro) && pythonMro is not null,
            $"{fullName}: resolved by {resolution.Rule} ({resolution.Detail}) to `{resolution.Module}.{resolution.Name}`, " +
            "which python does not import as an exception class.");

        var pythonIsOSError = pythonMro!.Contains("builtins.OSError");
        var clrIsOSError = typeof(global::Sharpy.OSError).IsAssignableFrom(type);
        Assert.True(pythonIsOSError == clrIsOSError,
            $"{fullName} (python `{resolution.Module}.{resolution.Name}`, MRO [{string.Join(", ", pythonMro!)}]): " +
            (pythonIsOSError
                ? "python's namesake is in the OSError family, so `except OSError` catches it; the CLR type does not derive from Core OSError."
                : "python's namesake is outside the OSError family; the CLR type derives from Core OSError, so `except OSError` would catch it."));
    }

    /// <summary>One python3 batch answering every (module, name) the map can look up.</summary>
    private static Dictionary<(string Module, string Name), string[]?> Oracle()
    {
        var python = PythonInterpreter.RequireOrSkip();
        lock (OracleLock)
        {
            if (_oracle is not null)
                return _oracle;

            var queries = new HashSet<(string Module, string Name)>();
            foreach (var type in GeneratedTypes())
            {
                // Every lookup the resolver can make: the table's answer, and the same-name pair it may ask the predicate.
                var tabled = Resolve(type, (_, _) => false);
                if (tabled.Rule == Rule.Spelling)
                    queries.Add((tabled.Module!, tabled.Name!));
                var stamp = type.GetCustomAttribute<global::Sharpy.SharpyModuleTypeAttribute>();
                if (tabled.Rule != Rule.Excluded && stamp is not null)
                    queries.Add((stamp.ModuleName, stamp.PythonName ?? type.Name));
            }

            var script = System.IO.Path.Combine(System.IO.Path.GetTempPath(), $"sharpy-stdlib-exception-mro-{Guid.NewGuid():N}.py");
            System.IO.File.WriteAllText(script, OracleScript);
            try
            {
                var ordered = queries.OrderBy(q => q.Module, StringComparer.Ordinal).ThenBy(q => q.Name, StringComparer.Ordinal).ToArray();
                var lines = python.RunBatch(script,
                    ordered.Select(q => System.Text.Json.JsonSerializer.Serialize(new Dictionary<string, string> { ["module"] = q.Module, ["name"] = q.Name })));
                var result = new Dictionary<(string, string), string[]?>();
                foreach (var line in lines)
                {
                    using var doc = System.Text.Json.JsonDocument.Parse(line);
                    var root = doc.RootElement;
                    var mro = root.GetProperty("mro");
                    result[(root.GetProperty("module").GetString()!, root.GetProperty("name").GetString()!)] =
                        mro.ValueKind == System.Text.Json.JsonValueKind.Null ? null : mro.EnumerateArray().Select(e => e.GetString()!).ToArray();
                }
                Assert.Equal(ordered.Length, result.Count);
                _oracle = result;
                return result;
            }
            finally
            {
                System.IO.File.Delete(script);
            }
        }
    }
}
